<?php
require_once __DIR__ . '/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('products.php');}
verifyAdminCsrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';
try{if($action==='toggle'){$s=$pdo->prepare("SELECT is_active FROM products WHERE id=?");$s->execute([$id]);$p=$s->fetch();if(!$p)throw new Exception('Product not found');$new=$p['is_active']?0:1;$u=$pdo->prepare("UPDATE products SET is_active=? WHERE id=?");$u->execute([$new,$id]);setFlashMessage('success',$new?'Product activated.':'Product deactivated safely.');}elseif($action==='delete'){ $check=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE product_id=?');$check->execute([$id]);$hasOrders=(int)$check->fetchColumn()>0;if($hasOrders){$u=$pdo->prepare('UPDATE products SET is_active=0 WHERE id=?');$u->execute([$id]);setFlashMessage('success','Product has order history, so it was safely deactivated instead of permanently deleted.');}else{$d=$pdo->prepare('DELETE FROM products WHERE id=?');$d->execute([$id]);setFlashMessage('success','Product deleted successfully.');}}else{throw new Exception('Unknown action');}}catch(Throwable $e){setFlashMessage('error','Could not update product: '.$e->getMessage());}redirect('products.php');
